// @bun
// src/index.ts
import { fileURLToPath } from "url";
import { dirname, resolve } from "path";
import { existsSync } from "fs";
var DEFAULTS = {
  enableFinanceAuditCommand: true,
  enableFinanceNewCommand: true
};
function appendSkillPath(cfg, path) {
  if (!cfg.skills)
    cfg.skills = {};
  if (!Array.isArray(cfg.skills.paths))
    cfg.skills.paths = [];
  if (!cfg.skills.paths.includes(path)) {
    cfg.skills.paths.push(path);
  }
}
function mergeCommand(cfg, name, def) {
  if (!cfg.command)
    cfg.command = {};
  if (cfg.command[name])
    return;
  cfg.command[name] = def;
}
var plugin = async (input, options) => {
  const opts = { ...DEFAULTS, ...options ?? {} };
  const entryDir = dirname(resolve(fileURLToPath(import.meta.url)));
  const distSibling = resolve(entryDir, "..", ".opencode", "skills");
  const entrySibling = resolve(entryDir, ".opencode", "skills");
  const distSiblingAgents = resolve(entryDir, "..", ".agents", "skills");
  const entrySiblingAgents = resolve(entryDir, ".agents", "skills");
  const skillsPath = existsSync(distSibling) ? distSibling : existsSync(entrySibling) ? entrySibling : existsSync(distSiblingAgents) ? distSiblingAgents : entrySiblingAgents;
  const hooks = {
    config: async (cfg) => {
      appendSkillPath(cfg, skillsPath);
      if (opts.enableFinanceAuditCommand) {
        mergeCommand(cfg, "arch-finance-audit", {
          description: "Production-readiness audit for banking/insurance AI projects with NFREGA (\u91D1\u53D1\u30142026\u30158\u53F7) regulatory focus \u2014 high-risk approval, data drift, agent five-defenses, personal info training ban.",
          agent: "build",
          subtask: true
        });
      }
      if (opts.enableFinanceNewCommand) {
        mergeCommand(cfg, "arch-finance-new", {
          description: "New banking/insurance AI project architecture guidance with NFREGA compliance built-in \u2014 full lifecycle, risk classification, high-risk gates, autonomous-controllable infrastructure.",
          agent: "build",
          subtask: true
        });
      }
    }
  };
  return hooks;
};
var src_default = plugin;
export {
  src_default as default
};
